// Kontrollerar F54 Sidkarta: sidan finns, inget skript, inga externa resurser, alla fristående sidor
// och Vreta Sound Systems vyer står med, varje intern länk motsvarar en fil, inga .html-länkar,
// AI-märkning och länk i startsidans sidfot. En ny sida i public/ utan rad i sidkartan gör testet rött.
// AI-skapat (B-051). Generated by AI, Directed by MS.
const fs = require('fs');
const path = require('path');

const pub = 'public';
const fil = path.join(pub, 'sidkarta.html');
const finns = fs.existsSync(fil);
const html = finns ? fs.readFileSync(fil, 'utf8') : '';
const utanKommentarer = html.replace(/<!--[\s\S]*?-->/g, '');
const hrefs = [...utanKommentarer.matchAll(/href="([^"]*)"/g)].map((m) => m[1]);
const fattas = [];

// 1. Sidan finns, med språk, teckenkodning, rubrik och hopplänk.
const sidanFinns = finns &&
  /<html lang="sv">/.test(html) &&
  /<meta charset="utf-8">/i.test(html) &&
  /<h1>Sidkarta<\/h1>/.test(html) &&
  hrefs.includes('#innehall');

// 2. Inget skript och inga absoluta adresser i src/href (sajtens egna värdar inräknade).
const ingetSkript = finns && !/<script/i.test(html) && !/(src|href)="https?:\/\//i.test(html);

// 3. Varje fristående sida i public/ (utom startsidan, sidkartan och nyhetsbrevet) har en rad.
const fristaende = fs.readdirSync(pub)
  .filter((f) => f.endsWith('.html'))
  .filter((f) => f !== 'index.html' && f !== 'sidkarta.html' && !/^nyhetsbrev/.test(f))
  .map((f) => '/' + f.replace(/\.html$/, ''));
const kravda = [...fristaende, '/vreta-sound-system', '/vreta-sound-system/en', '/vreta-sound-system/mixer'];
for (const k of kravda) if (!hrefs.includes(k)) fattas.push('saknar rad: ' + k);
const allaSidorMed = finns && kravda.every((k) => hrefs.includes(k));

// 4. Varje intern länk utan # motsvarar en fil.
const interna = hrefs.filter((h) => h.startsWith('/') && !h.includes('#'));
function harFil(h) {
  if (h === '/') return fs.existsSync(path.join(pub, 'index.html'));
  const v = h.replace(/^\//, '').replace(/\/$/, '');
  return fs.existsSync(path.join(pub, v + '.html')) || fs.existsSync(path.join(pub, v, 'index.html'));
}
for (const h of interna) if (!harFil(h)) fattas.push('länken leder inte till en fil: ' + h);
const lankarnaFinns = finns && interna.length > 0 && interna.every(harFil);

// 5. Inga länkar som slutar på .html.
const ingaHtmlLankar = finns && !hrefs.some((h) => /\.html(#|$)/.test(h));

// 6. AI-märkning.
const aiMarkt = html.includes('AI-skapat') && html.includes('Generated by AI, Directed by MS');

// 7. Länk i startsidans sidfot.
const index = fs.readFileSync(path.join(pub, 'index.html'), 'utf8');
const sidfot = (index.match(/<footer>[\s\S]*?<\/footer>/) || [''])[0];
const sidfotLankar = sidfot.includes('href="/sidkarta"');

const krav = { sidanFinns, ingetSkript, allaSidorMed, lankarnaFinns, ingaHtmlLankar, aiMarkt, sidfotLankar };
const ok = Object.values(krav).every(Boolean);
if (!ok && fattas.length) console.error(fattas.join('\n'));
console.log(JSON.stringify({ ...krav, ok }));
process.exit(ok ? 0 : 1);
